/// <summary>
/// The class <c>UPSPricingAttributeRepository</c> is used as center place holding pricing attributes and pricing attribute providers.
/// </summary>
public static class UPSPricingAttributeRepository
{
    public static str CacheScope = classStr(UPSPricingAttributeRepository);
    public static str PricingAttrCacheKey = strFmt('cache-%1', classStr(UPSIPricingAttribute));
    public static str PricingAttrProviderCacheKey = strFmt('cache-%1', classStr(UPSIPricingAttributeProvider));

}

Method.Source:
private static Map getPricingAttributeProviders()
{
    List attrProviderList = SysExtensionAppClassFactory::getClassInstanceListFromSysAttribute(
            classStr(UPSIPricingAttributeProvider),
            new UPSPricingMetadataDiscoveryAttribute());
    ListEnumerator providerEnumerator = attrProviderList.getEnumerator();
    UPSIPricingAttributeProvider pricingAttrProvider;
    Map pricingAttributeProviders = new Map(Types::Integer, Types::Class);

    while(providerEnumerator.moveNext())
    {
        pricingAttrProvider = providerEnumerator.current();

        pricingAttributeProviders.add(classIdGet(pricingAttrProvider), pricingAttrProvider);
    }

    return pricingAttributeProviders;
}

private static Map getPricingAttributes()
{
    List attrList = SysExtensionAppClassFactory::getClassInstanceListFromSysAttribute(
            classStr(UPSIPricingAttribute),
            new UPSPricingMetadataDiscoveryAttribute());
    ListEnumerator attrEnumerator = attrList.getEnumerator();
    UPSIPricingAttribute pricingAttr;
    Map pricingAttributes = new Map(Types::Integer, Types::Class);

    while(attrEnumerator.moveNext())
    {
        pricingAttr = attrEnumerator.current();

        pricingAttributes.add(classIdGet(pricingAttr), pricingAttr);
    }

    return pricingAttributes;
}

/// <summary>
/// Get cached pricing attr map.
/// </summary>
/// <returns>The map.</returns>
public static List getAllPricingAttributes()
{
    List pricingAttrs = new List(Types::Class);

    MapEnumerator attrEnum = UPSPricingAttributeRepository::pricingAttributes().getEnumerator();
    while (attrEnum.moveNext())
    {
        pricingAttrs.addEnd(attrEnum.currentValue());
    }

    MapEnumerator providerEnum = UPSPricingAttributeRepository::pricingAttributeProviders().getEnumerator();
    UPSIPricingAttributeProvider provider;
    SetEnumerator providerAttrEnum;
    while (providerEnum.moveNext())
    {
        provider = providerEnum.currentValue();
        providerAttrEnum = provider.getPricingAttributes().getEnumerator();

        while (providerAttrEnum.moveNext())
        {
            pricingAttrs.addEnd(providerAttrEnum.current());
        }
    }

    return pricingAttrs;
}

/// <summary>
/// Get temporay price attribute records; these records are to be consumed as form control lookup datasource.
/// </summary>
/// <param name = "_sourceLevel">The source level of price attribute.</param>
/// <returns>Price attribute records.</returns>
public static UPSPricingAttributeTmp getPriceAttributeTmp(UPSPricingAttributeSourceLevel _sourceLevel)
{
    // TODO: retrieve source level matched price attribute instances only.
    UPSPricingAttributeTmp priceAttrTmp;
    priceAttrTmp.clear();

    UPSPricingAttributeRepository::getPricingAttributes();

    List attributes = UPSPricingAttributeRepository::getAllPricingAttributes();
    Enumerator enum = attributes.getEnumerator();

    UPSIPricingAttribute pricingAttr;
    UPSPricingAttributeLink link;
    while (enum.moveNext())
    {
        pricingAttr = enum.current();
        link = UPSPricingAttributeRepository::toPriceAttributeLink(pricingAttr);
        priceAttrTmp.AttributeName = link.AttributeName;
        priceAttrTmp.PriceAttributeClassId = link.PriceAttributeClassId;
        priceAttrTmp.TypeName = link.TypeName;
        priceAttrTmp.ProviderClassId = link.AttributeProviderClassId;
        priceAttrTmp.insert();
    }

    return priceAttrTmp;
}

/// <summary>
/// Construct pricing attribute by class id and name.
/// </summary>
/// <param name = "_attrClassId">The class id of pricing attribute.</param>
/// <param name = "_attrProviderClassId">The class id of pricing attribute provider.</param>
/// <param name = "_attrName">The name of pricing attribute.</param>
/// <param name = "_attrTypeName">The type name of pricing attribute.</param>
/// <returns>The pricing attribute.</returns>
public static UPSIPricingAttribute priceAttribute(ClassId _attrClassId, ClassId _attrProviderClassId = 0, Name _attrName = '', str _attrTypeName = '')
{
    UPSIPricingAttribute pricingAttr;

    if (_attrClassId == classNum(UPSPricingAttributeEcoResAttribute))
    {
        if (!_attrProviderClassId || !_attrName)
        {
            throw error(strFmt(
                "@UnifiedPricingService:UPSPricingAttributeRepository_MissigIdentification",
                classStr(UPSPricingAttributeProviderEcoResProductAttribute),
                classStr(UPSPricingAttributeEcoResAttribute)));
        }

        if (!UPSPricingAttributeRepository::pricingAttributeProviders().exists(_attrProviderClassId))
        {
            throw error(strFmt(
                "@UnifiedPricingService:UPSPricingAttributeRepository_AttributeProviderDoesNotExist",
                _attrProviderClassId));
        }

        pricingAttr = new UPSPricingAttributeEcoResAttribute(
            _attrName,
            _attrTypeName,
            UPSPricingAttributeRepository::pricingAttributeProviders().lookup(_attrProviderClassId));
    }
    else
    {
        if (UPSPricingAttributeRepository::pricingAttributes().exists(_attrClassId))
        {
            pricingAttr = UPSPricingAttributeRepository::pricingAttributes().lookup(_attrClassId);
        }
        else
        {
            throw error(strFmt("@UnifiedPricingService:UPSPricingAttributeRepository_AttributeDoesNotExist", _attrClassId, _attrName));
        }
    }

    return pricingAttr;
}

internal static UPSPricingAttributeLink toPriceAttributeLink(UPSIPricingAttribute _pricingAttr)
{
    // TODO later on maybe move to interface.
    UPSPricingAttributeLink link;

    link.AttributeName = _pricingAttr.getName();
    link.PriceAttributeClassId = classIdGet(_pricingAttr);

    if (link.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute))
    {
        link.AttributeProviderClassId = (_pricingAttr as UPSPricingAttributeEcoResAttribute).getEcoResAttributeProviderId();
        link.TypeName = (_pricingAttr as UPSPricingAttributeEcoResAttribute).getAttributeType();
    }

    return link;
}

internal static UPSPricingAttributeSourceDiscoveryAttribute getPricingSourceDetail(UPSIPricingAttribute _pricingAttr)
{
    // Only use this method on small batch of pricing attribute (e.g. a set of attribute fixed source level)
    ClassId attrClassId = classIdGet(_pricingAttr);
    DictClass dictClass;

    if (attrClassId == classNum(UPSPricingAttributeEcoResAttribute))
    {
        attrClassId = (_pricingAttr as UPSPricingAttributeEcoResAttribute).getEcoResAttributeProviderId();
    }

    dictClass = new DictClass(attrClassId);
    return dictClass.getAttribute(attributeStr(UPSPricingAttributeSourceDiscoveryAttribute)) as UPSPricingAttributeSourceDiscoveryAttribute;
}

private static Map pricingAttributes()
{
    SysGlobalCache cache = classFactory.globalCache();
    if (cache.isSet(
        UPSPricingAttributeRepository::CacheScope,
        UPSPricingAttributeRepository::PricingAttrCacheKey))
    {
        return cache.get(
            UPSPricingAttributeRepository::CacheScope,
            UPSPricingAttributeRepository::PricingAttrCacheKey);
    }
    else
    {
        Map pricingAttrs = UPSPricingAttributeRepository::getPricingAttributes();

        cache.set(
            UPSPricingAttributeRepository::CacheScope,
            UPSPricingAttributeRepository::PricingAttrCacheKey,
            pricingAttrs);

        return pricingAttrs;
    }
}

private static Map pricingAttributeProviders()
{
    SysGlobalCache cache = classFactory.globalCache();
    if (cache.isSet(
        UPSPricingAttributeRepository::CacheScope,
        UPSPricingAttributeRepository::PricingAttrProviderCacheKey))
    {
        return cache.get(
            UPSPricingAttributeRepository::CacheScope,
            UPSPricingAttributeRepository::PricingAttrProviderCacheKey);
    }
    else
    {
        Map pricingAttrProviders = UPSPricingAttributeRepository::getPricingAttributeProviders();

        cache.set(
            UPSPricingAttributeRepository::CacheScope,
            UPSPricingAttributeRepository::PricingAttrProviderCacheKey,
            pricingAttrProviders);

        return pricingAttrProviders;
    }
}
